arguments.new_str:
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train model at startup
var modelPath = TrainModel(builder.Environment.ContentRootPath);

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

static string TrainModel(string contentRoot)
{
    var mlContext = new MLContext(seed: 42);
    var dataPath = Path.Combine(contentRoot, "Data", "tickets.csv");
    var modelPath = Path.Combine(contentRoot, "Data", "ticket_model.zip");

    var data = mlContext.Data.LoadFromTextFile<TicketInput>(
        dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.3, seed: 42);

    var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject))
        .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
        .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
        .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
        .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    Console.WriteLine("Training ticket classification model...");
    var model = pipeline.Fit(split.TrainSet);

    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

    Console.WriteLine("=== Model Evaluation Metrics ===");
    Console.WriteLine($"  Macro Accuracy:     {metrics.MacroAccuracy:F4}");
    Console.WriteLine($"  Micro Accuracy:     {metrics.MicroAccuracy:F4}");
    Console.WriteLine($"  Log Loss:           {metrics.LogLoss:F4}");
    Console.WriteLine($"  Log Loss Reduction: {metrics.LogLossReduction:F4}");

    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");

    return modelPath;
}

